from fractions import Fraction

def is_martingale(values, n, p):
    """values maps every toss prefix of length 0..n (a string of H and T) to a number."""
    p = Fraction(p)
    for prefix in values:
        if len(prefix) < n:
            if p * values[prefix + 'H'] + (1 - p) * values[prefix + 'T'] != values[prefix]:
                return False
    return True

def doob(f, n, p):
    """E[f | F_k] for k = 0..n, as a dict from each prefix to a Fraction. f takes the full path."""
    p = Fraction(p)
    out = {}
    def go(prefix):
        if len(prefix) == n:
            out[prefix] = Fraction(f(prefix))
        else:
            out[prefix] = p * go(prefix + 'H') + (1 - p) * go(prefix + 'T')
        return out[prefix]
    go('')
    return out
